pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 dummy) public {
        // dummy serves only to enable fuzzing; the property is independent of caller
        address owner = address(uint160(dummy % 2**160));
        vm.assume(owner != address(0));
        vm.prank(owner);
        // Setup: transfer ownership to fuzzed owner
        // C inherits sGuardPlus whose constructor sets __owner = deployer.
        // There is no ownership transfer function, so we must call sudicideAnyone as deployer.
        // Since deployer is fixed, we fuzz dummy just to satisfy the requirement.
        // The invariant is: sudicideAnyone() never reverts when called by the owner.
        bool ok;
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

