pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // 1. bound to a reasonable ether amount
        amount = bound(amount, 1, 100 ether);
        address owner = makeAddr("owner");
        vm.deal(owner, amount);
        vm.prank(owner);
        c = new C();
        vm.deal(address(c), amount);

        // 2. owner calls sudicideAnyone()
        vm.prank(owner);
        bool ok = true;
        try c.sudicideAnyone() {
        } catch {
            ok = false;
        }

        // 3. Property: If the call succeeded (ok == true), then the contract balance must be 0.
        //    If it reverted, the balance remains unchanged.
        //    The reference succeeds and transfers balance => balance == 0.
        //    The buggy reverts => balance == amount.
        assertTrue(!ok || address(c).balance == 0);
    }
}

