pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner) public {
        vm.assume(owner != address(0) && owner != address(this) && owner != address(c));
        vm.prank(owner);
        // The onlyOwner modifier will restrict calls; we test with the actual owner from construction
        // We need to use the actual owner to make the call succeed. The constructor sets __owner = msg.sender (the test contract).
        // We'll use the test contract as the owner and fuzz other inputs, but sudicideAnyone has no params.
        // We can fuzz the owner to show it only works with the true owner, and the property is general.
        // However, the test must show the property holds for all inputs where the call succeeds (owner calls).
        // Let's make the test use the actual owner from setUp (which is the test contract itself) to satisfy the general property.
        // We'll use vm.startPrank to simulate owner.
        // The fuzz param 'owner' is not used as sender; we fuzz a dummy parameter to satisfy the fuzzer requirement.
        // Actually, the rule is about the effect of a successful owner call, so the sender must be the owner.
        // We'll use vm.prank(c.owner()) if owner is public, but __owner is private with no getter.
        // We can retrieve the owner from storage slot or use the constructor context; the test contract deployed C, so test contract is owner.
        // Best approach: use the test contract itself as the owner (as set in setUp) and fuzz a dummy param.
        // We need at least one fuzz param; we'll use a dummy address which we won't use as sender.
        // Assert that after sudicideAnyone() called by owner, the contract has no code.
        (bool success, ) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));
        // The call should succeed (no revert) and self-destruct.
        uint256 codeSize;
        assembly {
            codeSize := extcodesize(c)
        }
        // The general rule: after a successful owner call to sudicideAnyone, the contract's code size is 0.
        // In the buggy version, the call reverts, so codeSize remains > 0.
        assertTrue(codeSize == 0);
    }
}

