pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Keep amount in a wide admissible range
        vm.assume(amount > 0 && amount <= address(this).balance);
        // Fund the contract with fuzzed amount of Ether
        vm.deal(address(c), amount);
        // Get the contract's balance before the call
        uint256 balanceBefore = address(c).balance;
        // Make the call as the owner (the deployer of C is the setUp's caller, which is this test contract)
        c.sudicideAnyone();
        // Assert: after the call, the contract's balance must be zero.
        // The reference selfdestruct sends all funds to the owner and destroys the contract,
        // so balance becomes 0. The buggy version sends to address(0) and fails selfdestruct,
        // leaving the balance unchanged at amount.
        assertTrue(address(c).balance == 0);
    }
}
